namespace {unsigned checks=0,mutations=0;bool live=false,fail_alloc=false;Result flush_result=0;size_t allocated=0;std::map<void*,size_t>allocations;std::string error;
std::array<std::vector<ndspWaveBuf*>,24>queues;std::array<float,24>gains{},rates{};
#define CHECK(x) do{++checks;if(!(x)){std::fprintf(stderr,"Geyser audio %d: %s (%s)\n",__LINE__,#x,error.c_str());std::exit(1);}}while(0)
size_t channel(int c){CHECK(c>=0&&c<24);++mutations;return size_t(c);}
void drain(int c){for(auto*w:queues[channel(c)])w->status=NDSP_WBUF_DONE;queues[size_t(c)].clear();}
void write(const std::filesystem::path&p,const std::vector<uint8_t>&bytes){std::filesystem::create_directories(p.parent_path());std::ofstream out(p,std::ios::binary);out.write(reinterpret_cast<const char*>(bytes.data()),std::streamsize(bytes.size()));CHECK(bool(out));}
std::vector<uint8_t>read(const std::filesystem::path&p){std::vector<uint8_t>bytes;CHECK(read_file(p.string().c_str(),bytes,8*1024*1024,error));return bytes;}
}
Result ndspInit(){live=true;return 0;}void ndspExit(){for(int c=0;c<24;++c)drain(c);live=false;}void ndspSetMasterVol(float){++mutations;}
void ndspChnReset(int c){channel(c);ndsp_test_reset_sequence(c);drain(c);}void ndspChnWaveBufClear(int c){drain(c);}void ndspChnSetPaused(int c,bool){channel(c);}void ndspChnSetInterp(int c,int){channel(c);}void ndspChnSetFormat(int c,int){channel(c);}void ndspChnSetRate(int c,float rate){CHECK(std::isfinite(rate)&&rate>0);rates[channel(c)]=rate;}
void ndspChnSetMix(int c,float*mix){CHECK(mix[0]==mix[1]);gains[channel(c)]=mix[0];}
void*linearAlloc(size_t n){if(fail_alloc)return nullptr;auto*p=std::malloc(n);if(p){allocations[p]=n;allocated+=n;}return p;}
void linearFree(void*p){auto found=allocations.find(p);CHECK(found!=allocations.end());const auto first=reinterpret_cast<uintptr_t>(p),last=first+found->second;for(const auto&q:queues)for(const auto*w:q){const auto address=reinterpret_cast<uintptr_t>(w->data_pcm16);CHECK(address<first||address>=last);}allocated-=found->second;allocations.erase(found);std::free(p);}
Result DSP_FlushDataCache(const void*p,uint32_t n){CHECK(p&&n&&n<=512*1024);return flush_result;}
void ndspChnWaveBufAdd(int c,ndspWaveBuf*w){CHECK(live&&w&&w->data_pcm16&&w->nsamples&&w->nsamples<=2048&&!w->looping);ndsp_test_assign_sequence(c,w);w->status=NDSP_WBUF_QUEUED;queues[channel(c)].push_back(w);}
uint32_t ndspGetDroppedFrames(){return 0;}uint32_t ndspChnGetSamplePos(int c){channel(c);return 0;}uint16_t ndspChnGetWaveBufSeq(int c){const auto&q=queues[channel(c)];return q.empty()?0:q.front()->sequence_id;}

void registry_audio_case(const char*family_file,ctr::GeyserAudioService&service,ctr::AudioPlayer&player,int output_channel){
 upstream::GeyserLifecycleData family;upstream::GeyserLifecycle life;upstream::PoisonHoleTimers timers;CHECK(family.load_file(family_file,error)&&life.prepare(family,3,error)&&timers.prepare(family.poison(),3,error)&&service.activate(3,error));const auto bgm=queues[0];const auto music=player.observe_music();
 CHECK(timers.advance_hole_idle(3,family.poison().holes().front().id,family.poison().holes().front().delay+family.poison().holes().front().interval+1,true,error)&&life.receive_spawns(3,timers,error)&&service.sync_lifecycle(3,life,{{0,0},320,1},error));CHECK(!life.instances().empty());const auto id=life.instances().front();CHECK(!service.bind(3,id,error));CHECK(life.flush_additions(3,error)&&life.advance_animations_idle(3,.1,true,error));const auto waiting=life.commands().size();const auto before=mutations;CHECK(waiting>0&&!service.sync_lifecycle(3,life,{{0,0},0,1},error)&&life.commands().size()==waiting&&mutations==before);CHECK(service.sync_lifecycle(3,life,{family.poison().holes().front().position,320,1},error)&&life.commands().empty()&&mutations==before);CHECK(service.update(error)&&!queues[size_t(output_channel)].empty());
 CHECK(life.player_signal(3,timers,true,error)&&service.sync_lifecycle(3,life,{{0,0},320,1},error));drain(output_channel);CHECK(service.update(error)&&queues[size_t(output_channel)].empty());CHECK(life.player_signal(3,timers,false,error)&&life.advance_animations_idle(3,3,true,error));auto named=service.global_voice();CHECK(life.flush_methods(3,{{id,{true,false,false,false}}},named,error)&&service.sync_lifecycle(3,life,{{0,0},320,1},error));CHECK(service.global_voice()==upstream::GeyserNamedVoice::Playing);std::vector<upstream::PoisonSpawnRequest>removed;CHECK(life.retire_queued(3,removed,error)&&removed.size()==1&&service.sync_lifecycle(3,life,{{0,0},320,1},error));upstream::GeyserPlayback deleted;CHECK(!service.observe()->inspect(3,id,deleted,error));CHECK(life.retire_scene(3,error)&&service.retire_scene(3,error));
 unsigned loops=0;while(service.global_voice()==upstream::GeyserNamedVoice::Playing){CHECK(++loops<200);drain(output_channel);CHECK(service.update(error));}drain(output_channel);CHECK(service.update(error)&&queues[0]==bgm&&player.observe_music().generation==music.generation);
}
