 std::vector<std::vector<uint8_t>>pcms;size_t total=0;for(uint32_t n=0;n<data.bank().count();++n){const auto a=data.bank().asset(n);pcms.push_back(read(media/a.pcm_path));CHECK(pcms.back().size()==a.pcm_bytes);write(scratch/a.pcm_path,pcms.back());total+=a.pcm_bytes;}
