 for(uint32_t n=0;n<data.bank().count();++n){const auto a=data.bank().asset(n);CHECK(std::filesystem::remove(scratch/a.pcm_path));}
 CHECK(!service.activate(0,error));CHECK(service.activate(1,error));CHECK(service.bind(1,1,error));CHECK(!service.bind(1,1,error));CHECK(!service.bind(2,2,error));CHECK(!service.activate(2,error));const auto pool=ctr::region_channel_pool::owners();size_t claims=0,slot=SIZE_MAX;for(size_t n=0;n<pool.size();++n)if(pool[n]!=initial_pool[n]){++claims;slot=n;}CHECK(claims==1&&slot<pool.size());const int output_channel=int(ctr::region_channel_pool::first_channel+slot);CHECK(rates[size_t(output_channel)]==44100&&gains[size_t(output_channel)]==1);
