 CHECK(actor.player_signal(1,1,true,error));CHECK(service.sync(1,1,actor,{0,0},listener,error));drain(output_channel);CHECK(service.update(error)&&queues[size_t(output_channel)].empty());CHECK(actor.tree_notification(1,1,false,false,error));CHECK(service.sync(1,1,actor,{0,0},listener,error));CHECK(service.update(error)&&queues[size_t(output_channel)].size()==3);CHECK(service.retire_actor(1,1,error));CHECK(actor.retire(1,1,error));CHECK(!service.retire_actor(1,1,error));
