 unsigned loops=0;while(service.global_voice()==upstream::GeyserNamedVoice::Playing){CHECK(++loops<200);drain(output_channel);CHECK(service.update(error));}CHECK(service.global_voice()==upstream::GeyserNamedVoice::Idle);drain(output_channel);CHECK(service.update(error));CHECK(ctr::region_channel_pool::owners()==initial_pool);CHECK(queues[0]==bgm&&player.observe_music().generation==music.generation);
